import{stats}from"../components/StatsChart/StatsChart";import{AppState}from"../store/AppState";export var statsService={getBlockedTime:function(){return JSON.parse(window.external.SendStats("web-app-blocked-time","","all",AppState.statsBlockedWebStart.unix(),AppState.statsBlockedWebEnd.unix()))},getBlockedCount:function(){return JSON.parse(window.external.SendStats("web-app-blocked","","all",AppState.statsBlockedAppStart.unix(),AppState.statsBlockedAppEnd.unix()))},getWebStats:function(t,e,a){return JSON.parse(window.external.SendStats("web-"+t,e,a,AppState.statsWebStart.unix(),AppState.statsWebEnd.unix()))},getAppStats:function(t,e,a){return JSON.parse(window.external.SendStats("app-"+t,e,a,AppState.statsAppStart.unix(),AppState.statsAppEnd.unix()))},exportCsv:function(t){window.external.ExportStats(t)}};